function mint(n){return 'JAH-BM-'+String(n).padStart(6,'0');}
function validId(s){return /^JAH-[A-Z]{2}-\d{6}$/.test(s);}
var ids=[mint(10),mint(9),mint(100)].sort();
console.log('FIXED: sorted padded IDs = '+JSON.stringify(ids));
assert(ids[0]==='JAH-BM-000009','fixed: numeric order restored');
assert(validId('JAH-BM-000001')===true && validId('JAH-BM-1')===false,'fixed: validator enforces padding');

function editionOf(slug,base){ if(slug===base)return 'public'; if(slug===base+'-signature')return 'signature'; return 'unknown'; }
var e1=editionOf('benchmark-database','benchmark-database');
var e2=editionOf('benchmark-database-signature','benchmark-database');
console.log('FIXED: public->'+e1+', signature->'+e2);
assert(e1==='public' && e2==='signature','fixed: exact-boundary routing is unambiguous');
assert(editionOf('benchmark-database-signatures','benchmark-database')==='unknown','fixed: near-miss slugs rejected');

function chunkOf(n,size){return 'chunk-'+String(Math.floor((n-1)/size)+1).padStart(4,'0');}
var seen={};
for(var i=1;i<=300;i++){var c=chunkOf(i,150); seen[c]=(seen[c]||0)+1;}
console.log('FIXED: chunk-0001='+seen['chunk-0001']+', chunk-0002='+seen['chunk-0002']);
assert(chunkOf(150,150)==='chunk-0001' && chunkOf(151,150)==='chunk-0002','fixed: boundaries exact');
assert(seen['chunk-0001']===150 && seen['chunk-0002']===150,'fixed: 150 each, no overlap, no gap');

function generate(n){var out=[]; for(var i=0;i<n;i++)out.push({id:i+1}); return out;}
var got=generate(5);
console.log('FIXED: requested 5, emitted '+got.length);
assert(got.length===5,'fixed: exactly n emitted');
assert(got[0].id===1 && got[4].id===5,'fixed: ordinals 1..n');

function rankOf(id){var h=0; for(var i=0;i<id.length;i++)h=(h*33+id.charCodeAt(i))>>>0; return 1+(h%15);}
var ok=true, seen={};
for(var i=0;i<60000;i++){var r=rankOf('JAH-BM-'+i); if(r<1||r>15)ok=false; seen[r]=1;}
console.log('FIXED: all ranks in 1..15 = '+ok+', ranks covered = '+Object.keys(seen).length);
assert(ok===true,'fixed: range holds for 60000 IDs');
assert(Object.keys(seen).length===15,'fixed: all 15 ranks reachable');

var runCounter=0;
function gen(n,seed){function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
 var s=(seed===undefined)?(Date.now()^(++runCounter*2654435761)):seed;
 var r=mulberry32(s>>>0),out=[]; for(var i=0;i<n;i++)out.push(Math.floor(r()*1e9)); return out;}
var a=gen(50), b=gen(50);
var c=gen(50,7), d=gen(50,7);
console.log('FIXED: default runs differ='+(JSON.stringify(a)!==JSON.stringify(b))+', explicit seed reproduces='+(JSON.stringify(c)===JSON.stringify(d)));
assert(JSON.stringify(c)===JSON.stringify(d),'fixed: explicit seed still reproducible for tests');

function renderArchive(count,pageSize){ if(count===0)return {pages:0,empty:true,message:'0 records — the database is growing toward one million.'};
 var pages=[]; for(var p=0;p<Math.ceil(count/pageSize);p++)pages.push(p+1); return {pages:pages.length,empty:false}; }
var z=renderArchive(0,200), n=renderArchive(250,200);
console.log('FIXED: empty -> '+JSON.stringify(z)+', 250 records -> '+n.pages+' pages');
assert(z.empty===true && z.pages===0,'fixed: explicit empty state');
assert(n.pages===2 && n.empty===false,'fixed: normal paging intact');

function project(now,target,perDay){ if(!(perDay>0))return {days:null,status:'stalled'}; return {days:Math.ceil((target-now)/perDay),status:'marching'}; }
var z=project(24,1000000,0), n=project(24,1000000,24);
console.log('FIXED: stalled -> '+JSON.stringify(z)+', marching -> '+n.days+' days');
assert(z.status==='stalled' && z.days===null,'fixed: zero rate yields stalled status');
assert(n.days===41666 && n.status==='marching','fixed: normal projection exact');

function sibling(slug){var suf='-signature'; return slug.slice(-suf.length)===suf?slug.slice(0,-suf.length):slug+suf;}
var a=sibling('benchmark-database-signature'), b=sibling('benchmark-database');
console.log('FIXED: sibling(sig)='+a+', sibling(pub)='+b);
assert(a==='benchmark-database','fixed: signature page links to public');
assert(b==='benchmark-database-signature','fixed: public page links to signature');
assert(sibling(sibling('x'))==='x','fixed: round-trip stable');

function label(r){ if(r.built_by==='system-generated')return 'generated';
 return r.edition==='signature'?'signature-generated-completion':'public-harvest'; }
var f=[
 {built_by:'system-generated',edition:'public'},
 {built_by:'assistant-built',edition:'signature'},
 {built_by:'assistant-built',edition:'public'}].map(label);
console.log('FIXED: labels = '+JSON.stringify(f));
assert(JSON.stringify(f)===JSON.stringify(['generated','signature-generated-completion','public-harvest']),'fixed: all three derivations correct');

function isBenchSuite(id){return /^JAH-BENCH-\d{6}$/.test(id);}
var yes=isBenchSuite('JAH-BENCH-000001'), no=isBenchSuite('JAH-BENCHMARK-000001');
console.log('FIXED: true ID accepted='+yes+', longer prefix rejected='+(!no));
assert(yes===true,'fixed: genuine JAH-BENCH- ID accepted');
assert(no===false,'fixed: JAH-BENCHMARK- ID rejected');
assert(isBenchSuite('JAH-BENCH-1')===false,'fixed: unpadded form rejected too');

function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
var html='<h1>'+esc('<script>alert(1)</script>')+'</h1>';
console.log('FIXED: '+html);
assert(html.indexOf('<script>')===-1,'fixed: no live script tag');
assert(html.indexOf('&lt;script&gt;')!==-1,'fixed: title visible as text');
assert(esc('a&b')==='a&amp;b','fixed: ampersand escaped first (no double-escape)');

function parseJsonl(text){return text.split('\n').filter(function(l){return l.trim().length>0;}).map(function(l){return JSON.parse(l);});}
var recs=parseJsonl('{"a":1}\n{"a":2}\n');
console.log('FIXED: parsed '+recs.length+' records');
assert(recs.length===2,'fixed: trailing newline ignored');
assert(recs[0].a===1 && recs[1].a===2,'fixed: records intact');

var zlib=require('zlib');
function loadChunk(buf){ try{ return {ok:true,data:zlib.gunzipSync(buf).toString('utf8')}; }
 catch(e){ return {ok:false,corrupt:true,error:String(e.message).slice(0,40)}; } }
var full=zlib.gzipSync('{"records":[1,2,3]}');
var cut=full.slice(0,full.length-10);
var r1=loadChunk(cut), r2=loadChunk(full);
console.log('FIXED: truncated -> '+JSON.stringify({ok:r1.ok,corrupt:r1.corrupt})+', full -> ok='+r2.ok);
assert(r1.ok===false && r1.corrupt===true,'fixed: corruption caught and flagged');
assert(r2.ok===true && r2.data==='{"records":[1,2,3]}','fixed: intact chunk loads');

function stamp(){return {node:process.version,at:new Date().toISOString()};}
function drift(stamped,running){return stamped.node===running?null:'version drift: recorded '+stamped.node+', running '+running;}
var s=stamp();
console.log('FIXED: stamped node='+s.node);
assert(/v\d+\.\d+\.\d+/.test(s.node),'fixed: version stamped in parseable form');
assert(drift(s,process.version)===null,'fixed: same version -> no drift');
assert(drift({node:'v18.0.0'},process.version)!==null,'fixed: changed version flagged');

function mergeCross(editions){var map={};
 editions.forEach(function(e){e.forEach(function(r){map[r.ed+':'+r.id]=r;});});
 return Object.keys(map).map(function(k){return map[k];});}
var out=mergeCross([[{id:'JAH-BENCHMARK-000001',ed:'public'}],[{id:'JAH-BENCHMARK-000001',ed:'signature'}]]);
console.log('FIXED: merged records='+out.length);
assert(out.length===2,'fixed: both editions survive');
assert(out[0].id==='JAH-BENCHMARK-000001','fixed: display ID unchanged');

function recount(chunks){return chunks.reduce(function(a,b){return a+b;},0);}
function restamp(entry,chunks){entry.record_count=recount(chunks); entry.stamped_at=new Date().toISOString().slice(0,10); return entry;}
var entry={slug:'x',record_count:24};
restamp(entry,[8,8,8,6]);
console.log('FIXED: restamped count='+entry.record_count);
assert(entry.record_count===30,'fixed: derived count matches actual');
assert(entry.stamped_at.length===10,'fixed: stamp date present');

function cardTagline(t){var s=t.length>120?t.slice(0,117)+'...':t; return '<p title="'+t.replace(/"/g,'&quot;')+'">'+s+'</p>';}
var long=new Array(401).join('x'), short='A short tagline.';
var c1=cardTagline(long), c2=cardTagline(short);
console.log('FIXED: long displays '+(c1.match(/<p[^>]*>(.*)<\/p>/)[1].length)+' chars, short untouched='+(c2.indexOf(short)!==-1));
assert(c1.indexOf('...')!==-1 && c1.match(/<p[^>]*>(.*)<\/p>/)[1].length===120,'fixed: capped at 120 with ellipsis');
assert(c2.indexOf(short)!==-1 && c2.indexOf('...')===-1,'fixed: short tagline untouched');
assert(c1.indexOf('title=')!==-1,'fixed: full text kept in title attribute');

