function resolvePattern(pat,files){var re=new RegExp('^'+pat.split('NNNN').join('\\d{4}')+'$'); return files.filter(function(f){return re.test(f);});}
function validatePattern(pat,files){var hits=resolvePattern(pat,files); if(hits.length===0)throw new Error('chunk_pattern matches no files: '+pat); return hits;}
var files=['data/x/chunks/chunk-0001.jsonl.gz','data/x/chunks/chunk-0002.jsonl.gz'];
var ok=validatePattern('data/x/chunks/chunk-NNNN.jsonl.gz',files);
var threw=false; try{validatePattern('data/x/chunk-NNNN.jsonl.gz',files);}catch(e){threw=true;}
console.log('FIXED: correct pattern hits='+ok.length+', wrong pattern throws='+threw);
assert(ok.length===2,'fixed: correct pattern resolves');
assert(threw===true,'fixed: wrong pattern fails loudly at build time');

