function validSlug(s){return /^[a-z0-9-]+$/.test(s);}
function transliterate(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');}
var t=transliterate('données-base');
console.log('FIXED: transliterated = '+t+', valid='+validSlug(t));
assert(t==='donnees-base','fixed: accents stripped deterministically');
assert(validSlug(t)===true,'fixed: result passes the ASCII slug pattern');
assert(validSlug('données-base')===false,'fixed: raw non-ASCII slug rejected');

